
use chrono::Datelike;
use serde::{Deserialize, Serialize};

use crate::structs::PrayerTimes;

pub const DEFAULT_MV_ISLAND_KEY: &str = "K. Male'";
pub const DEFAULT_MV_TIMESET_INDEX: usize = 57;
pub const DEFAULT_MV_COORDINATES: (&str, &str) = ("4.17503", "73.509878");

// embedded salatmv dataset; generated by build.rs into OUT_DIR/parsed_data.rs.
// ATOLL_DATA  : &[[&str; 4]; 20]     0:index, 1:eng_name, 2:dhi_name, 3:ar_name
// ISLAND_DATA : &[[&str; 10]; 205]   0:timeset_index, 1:island_index, 2:atoll_index,
//                                    3:eng_name, 4:dhi_name, 5:ar_name, 6:unknown,
//                                    7:latitude, 8:longitude, 9:unknown
// PT_DATA     : &[[u32; 8]; 15372]   0:timeset_index, 1:day, 2:fajr, 3:sun, 4:dhuhur,
//                                    5:asr, 6:magrib, 7:isha
include!(concat!(env!("OUT_DIR"), "/parsed_data.rs"));

/// unique atoll-prefixed key for an embedded island row: "K. Male'"
fn island_key(island: &[&str; 10]) -> String {
    // atoll references are 1-based ids into ATOLL_DATA
    let atoll_index: usize = island[2].parse::<usize>().unwrap_or(0).saturating_sub(1);
    format!("{}. {}", ATOLL_DATA[atoll_index][1], island[3])
}

/// sorted keys of every embedded island (settings island picker)
pub fn island_keys() -> Vec<String> {
    let mut keys: Vec<String> = ISLAND_DATA.iter().map(|row| island_key(row)).collect();
    keys.sort();
    keys
}

/// parse the full-year timeset belonging to an island key
pub fn timeset_for_island(key: &str) -> Option<TimeSetData> {
    let island = ISLAND_DATA.iter().find(|row| island_key(row) == key)?;
    let timeset_index: u32 = island[0].parse().ok()?;

    let data: Vec<Vec<u32>> = PT_DATA
        .iter()
        .filter(|row| row[0] == timeset_index)
        .map(|row| row.to_vec())
        .collect();
    if data.is_empty() {
        return None;
    }

    Some(TimeSetData {
        name: key.to_string(),
        details: None,
        coordinates: (island[7].to_string(), island[8].to_string()),
        data,
    })
}

/// General Data structs

#[derive(Debug, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct TimeSetData {
    pub name: String,
    pub details: Option<String>,
    pub coordinates: (String, String),
    pub data: Vec<Vec<u32>>,
}
impl TimeSetData {

    #[allow(dead_code)]
    pub fn list() -> Vec<String> {
        let Some(dirs) = directories::ProjectDirs::from("", "", "salatui") else {
            return Vec::new();
        };
        let Ok(entries) = std::fs::read_dir(dirs.data_dir()) else {
            return Vec::new();
        };
        let mut names: Vec<String> = entries
            .flatten()
            .filter(|e| e.path().is_file())
            .filter_map(|e| e.file_name().into_string().ok())
            .collect();
        names.sort();
        names
    }

    #[allow(dead_code)]
    pub fn load(name: &str) -> Result<TimeSetData, confy::ConfyError> {
        let dirs = directories::ProjectDirs::from("", "", "salatui").unwrap();
        let mut data_path = dirs.data_dir().to_path_buf();
        data_path.push(name);
        
        if std::path::Path::exists(&data_path) {
            let data = confy::load_path(data_path)?;
            Ok(data)
        }else{
            let err_path = data_path.to_str().unwrap().to_string();
            Err(confy::ConfyError::BadConfigDirectory(err_path))
        }
    }
    
    #[allow(dead_code)]
    pub fn save(&self, name: &str) -> Result<(), confy::ConfyError>{
        let dirs = directories::ProjectDirs::from("", "", "salatui").unwrap();
        let mut data_path = dirs.data_dir().to_path_buf();
        
        if std::path::Path::exists(&data_path) {
            data_path.push(name);
            confy::store_path(&data_path, self)?;
            Ok(())
            
        } else {
            match std::fs::create_dir(&data_path) {
                Ok(_) => println!("no data directory exists. creating"),
                Err(err) => println!("failed to create directory\n{err}"),
            };
            data_path.push(name);
            confy::store_path(&data_path, self)?;
            Ok(())
        }    
    }
    
    pub fn day_index(&self, date: chrono::NaiveDate) -> usize {
        let mut index = date.ordinal0() as usize;
        match (date.leap_year(), self.data.len() >= 366) {
            // 366-row table, ordinary year: skip over the unused Feb 29 slot
            (false, true) if index > 58 => index += 1,
            // 365-row table, leap year: compress post-Feb-29 dates back one slot
            (true, false) if index > 59 => index -= 1,
            _ => {}
        }
        index.min(self.data.len().saturating_sub(1))
    }

    pub fn data_from_day(&self, day: usize) -> PrayerTimes {
        PrayerTimes::from_vec(self.data[day].to_owned())
    }
    
}


#[test]
fn test_day_index_365_table() {
    // legacy layout: no Feb 29 slot
    let dataset = TimeSetData {
        name: String::new(),
        details: None,
        coordinates: (String::new(), String::new()),
        data: vec![vec![0]; 365],
    };
    let date = |y, m, d| chrono::NaiveDate::from_ymd_opt(y, m, d).unwrap();

    assert_eq!(dataset.day_index(date(2025, 1, 1)), 0);
    assert_eq!(dataset.day_index(date(2025, 2, 28)), 58);
    assert_eq!(dataset.day_index(date(2025, 3, 1)), 59);
    assert_eq!(dataset.day_index(date(2025, 12, 31)), 364);

    assert_eq!(dataset.day_index(date(2024, 2, 28)), 58);
    assert_eq!(dataset.day_index(date(2024, 2, 29)), 59);
    assert_eq!(dataset.day_index(date(2024, 3, 1)), 59);
    assert_eq!(dataset.day_index(date(2024, 12, 31)), 364);
}

#[test]
fn test_day_index_366_table() {
    // salatmv layout: Feb 29 slot present; ordinary years skip over it
    let dataset = TimeSetData {
        name: String::new(),
        details: None,
        coordinates: (String::new(), String::new()),
        data: vec![vec![0]; 366],
    };
    let date = |y, m, d| chrono::NaiveDate::from_ymd_opt(y, m, d).unwrap();

    assert_eq!(dataset.day_index(date(2025, 1, 1)), 0);
    assert_eq!(dataset.day_index(date(2025, 2, 28)), 58);
    assert_eq!(dataset.day_index(date(2025, 3, 1)), 60);
    assert_eq!(dataset.day_index(date(2025, 12, 31)), 365);

    assert_eq!(dataset.day_index(date(2024, 2, 28)), 58);
    assert_eq!(dataset.day_index(date(2024, 2, 29)), 59);
    assert_eq!(dataset.day_index(date(2024, 3, 1)), 60);
    assert_eq!(dataset.day_index(date(2024, 12, 31)), 365);
}

#[test]
fn test_timeset_for_island() {
    let parsed = timeset_for_island(DEFAULT_MV_ISLAND_KEY).expect("default island should parse");

    assert_eq!(parsed.name, DEFAULT_MV_ISLAND_KEY);
    assert_eq!(parsed.coordinates, (DEFAULT_MV_COORDINATES.0.to_string(), DEFAULT_MV_COORDINATES.1.to_string()));
    assert_eq!(parsed.data[0][0] as usize, DEFAULT_MV_TIMESET_INDEX);
    assert!(!parsed.data.is_empty());

    assert!(timeset_for_island("XX. Nowhere").is_none());
}

#[test]
fn test_island_keys() {
    let keys = island_keys();
    assert_eq!(keys.len(), ISLAND_DATA.len());
    assert!(keys.iter().any(|k| k == DEFAULT_MV_ISLAND_KEY));

    let mut sorted = keys.clone();
    sorted.sort();
    assert_eq!(keys, sorted);

    let unique: std::collections::HashSet<&String> = keys.iter().collect();
    assert_eq!(unique.len(), keys.len());
}
